from ortools.sat.python import cp_model
import itertools
import json

def compute_shortest_paths():
    """Compute all-pairs shortest paths on the undirected graph."""
    edges = {
        (1, 2): 10, (1, 3): 5, (1, 4): 7, (1, 5): 8,
        (2, 3): 2, (2, 4): 1, (2, 5): 6,
        (3, 4): 9, (3, 5): 2,
        (4, 5): 4
    }

    graph = {}
    for (u, v), w in edges.items():
        graph.setdefault(u, {})[v] = w
        graph.setdefault(v, {})[u] = w

    nodes = list(range(1, 6))

    INF = float('inf')
    dist = {i: {j: INF for j in nodes} for i in nodes}

    for i in nodes:
        dist[i][i] = 0
    for (u, v), w in edges.items():
        dist[u][v] = w
        dist[v][u] = w

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def main():
    N = list(range(1, 6))
    p = 2

    c = compute_shortest_paths()

    model = cp_model.CpModel()

    y = {i: model.NewBoolVar(f"y_{i}") for i in N}

    x = {}
    for i in N:
        for j in N:
            x[(i, j)] = model.NewBoolVar(f"x_{i}_{j}")

    model.Add(sum(y[i] for i in N) == p)

    for i in N:
        for j in N:
            model.Add(x[(i, j)] <= y[j])

    for i in N:
        model.Add(sum(x[(i, j)] for j in N) == 1)

    objective_terms = []
    for i in N:
        for j in N:
            objective_terms.append(int(c[i][j]) * x[(i, j)])

    model.Minimize(sum(objective_terms))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        synchronization_nodes = [i for i in N if solver.Value(y[i]) == 1]
        total_decoherence_expenditure = int(solver.ObjectiveValue())

        def get_path(i, j):
            if i == j:
                return [i]
            for k in N:
                if k != i and k != j and abs(c[i][j] - (c[i][k] + c[k][j])) < 1e-5:
                    left = get_path(i, k)
                    right = get_path(k, j)
                    return left + right[1:]
            return [i, j]

        quantum_entanglement_assignments = []
        for i in N:
            for j in N:
                if solver.Value(x[(i, j)]) == 1:
                    route = get_path(i, j)
                    cost = int(c[i][j])
                    quantum_entanglement_assignments.append([j, route, cost])
                    break

        print(json.dumps({
            "synchronization_nodes": synchronization_nodes,
            "total_decoherence_expenditure": total_decoherence_expenditure,
            "quantum_entanglement_assignments": quantum_entanglement_assignments
        }))
    else:
        print(json.dumps({
            "synchronization_nodes": [],
            "total_decoherence_expenditure": 0,
            "quantum_entanglement_assignments": []
        }))

if __name__ == "__main__":
    main()
